// Find the 'received' label ID among existing Gmail labels.
// If found, pass it through. If not found, output a flag so the next node creates it.
const labels = $input.first().json.labels ?? [];
const receivedLabel = labels.find(l => l.name.toLowerCase() === 'received');

if (receivedLabel) {
  return [{ json: { receivedLabelId: receivedLabel.id, needsCreate: false } }];
}
return [{ json: { receivedLabelId: null, needsCreate: true } }];

// Merge: whether we just created the label or it already existed,
// output a unified { receivedLabelId } for downstream nodes.
const item = $input.first().json;
// After creation the response is the label object with .id
// After pass-through the item has .receivedLabelId
// After continueOnFail the item may have .error — label already existed
const id = item.id ?? item.receivedLabelId ?? null;
return [{ json: { receivedLabelId: id } }];

// Extract normalised email fields + attachment info from the Gmail message.
// With simple:false the Gmail node returns the raw API response including
// payload.parts where attachments live.

const msg = $input.first().json;
const payload = msg.payload ?? {};
const headers = payload.headers ?? [];

const getHeader = (name) =>
  headers.find(h => h.name?.toLowerCase() === name.toLowerCase())?.value ?? '';

// Use n8n-extracted convenience fields first, then fall back to raw headers
const subject = msg.subject || msg.Subject || getHeader('Subject') || '';
const fromRaw = msg.from || msg.From || getHeader('From') || '';
const from = typeof fromRaw === 'object' ? (fromRaw.text ?? '') : (fromRaw ?? '');
const toRaw = msg.to || msg.To || getHeader('To') || '';
const to = typeof toRaw === 'object' ? (toRaw.text ?? '') : (toRaw ?? '');
const date = msg.date || getHeader('Date') || '';

// ── Decode body from Gmail API payload.parts (base64url) ──
// Gmail stores the body in MIME parts; walk recursively to find text/plain or text/html.
function decodeBase64url(str) {
  if (!str) return '';
  // base64url → base64
  let b64 = str.replace(/-/g, '+').replace(/_/g, '/');
  while (b64.length % 4) b64 += '=';
  return Buffer.from(b64, 'base64').toString('utf-8');
}

let bodyPlain = '';
let bodyHtml = '';

function extractBody(part) {
  if (!part) return;
  const mime = (part.mimeType || '').toLowerCase();
  const data = part.body?.data;
  if (mime === 'text/plain' && data && !bodyPlain) {
    bodyPlain = decodeBase64url(data);
  } else if (mime === 'text/html' && data && !bodyHtml) {
    bodyHtml = decodeBase64url(data);
  }
  if (Array.isArray(part.parts)) {
    for (const sub of part.parts) extractBody(sub);
  }
}
extractBody(payload);

// Strip HTML tags for plain text fallback
function stripHtml(html) {
  return html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?(p|div|tr|li)[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Priority: n8n decoded text → payload plain → payload html stripped → snippet
const body = msg.text || bodyPlain || (bodyHtml ? stripHtml(bodyHtml) : '') || msg.snippet || '';

// Walk payload.parts recursively to find attachments
const attachmentFilenames = [];
let msgAttachmentId = null;
let msgAttachmentName = null;

function scanParts(parts) {
  if (!Array.isArray(parts)) return;
  for (const part of parts) {
    if (part.filename && part.filename.length > 0) {
      attachmentFilenames.push(part.filename);
      if (part.filename.toLowerCase().endsWith('.msg') && !msgAttachmentId) {
        msgAttachmentId = (part.body && part.body.attachmentId) ? part.body.attachmentId : null;
        msgAttachmentName = part.filename;
      }
    }
    if (part.parts) scanParts(part.parts);
  }
}
scanParts(payload.parts ?? []);

return [{
  json: {
    // Gmail identifiers — needed by Build Gmail Modify Payload
    id: msg.id,
    threadId: msg.threadId,
    labelIds: msg.labelIds ?? [],
    snippet: msg.snippet ?? '',
    // Normalised email fields
    subject,
    from,
    to,
    date,
    body,
    // Attachment metadata
    hasAttachments: attachmentFilenames.length > 0,
    attachmentFilenames,
    msgAttachmentId,
    msgAttachmentName,
  }
}];

// Merge the downloaded .msg attachment data back with the normalised email fields.
// The Gmail attachment API returns { size, data } where data is base64url-encoded bytes.
const emailData = $('Extract Email + Attachment Info').item.json;
const attachmentResp = $input.first().json;

return [{
  json: {
    ...emailData,
    // base64url bytes of the .msg file — API will parse with msgreader
    msgAttachmentData: attachmentResp.data ?? null,
  }
}];

// Build Gmail modify payload: mark read, add 'received' label, remove INBOX.
// Reference the Extract node for the original Gmail message ID (not the API response).
const messageId = $('Extract Email + Attachment Info').first().json.id;
const receivedLabelId = $('Set Label ID').first().json.receivedLabelId;

return [{
  json: {
    messageId,
    addLabelIds: receivedLabelId ? [receivedLabelId] : [],
    removeLabelIds: ['INBOX', 'UNREAD'],
    markRead: true
  }
}];
